package types

// Role identifies the sender of a chat message.
type Role string

const (
	// RoleSystem marks a system prompt message.
	RoleSystem Role = "system"

	// RoleUser marks a message from the user.
	RoleUser Role = "user"

	// RoleAssistant marks a message generated by the model.
	RoleAssistant Role = "assistant"

	// RoleTool marks a message carrying a tool result.
	RoleTool Role = "tool"
)

// ChatMessage is the universal message format shared across
// Agent (sends messages), Gateway (routes them), Torch (generates responses),
// and Shield (redacts PII from them).
type ChatMessage struct {
	Version    int        `json:"version"`
	Role       Role       `json:"role"`
	Content    string     `json:"content"`
	Name       string     `json:"name,omitempty"`       // Optional sender name
	ToolCalls  []ToolCall `json:"tool_calls,omitempty"` // Assistant-initiated tool calls
	ToolCallID string     `json:"tool_call_id,omitempty"`
}

// ToolCall represents a function call requested by the model.
type ToolCall struct {
	Version  int          `json:"version"`
	ID       string       `json:"id"`
	Type     string       `json:"type"` // always "function"
	Function FunctionCall `json:"function"`
}

// FunctionCall contains the function name and JSON-encoded arguments.
type FunctionCall struct {
	Version   int    `json:"version"`
	Name      string `json:"name"`
	Arguments string `json:"arguments"` // JSON string
}

// InferenceRequest is the standard request format for any module
// that performs inference (Torch directly, or Gateway routing to cloud).
type InferenceRequest struct {
	Version     int           `json:"version"`
	Model       ModelID       `json:"model"`
	Messages    []ChatMessage `json:"messages"`
	Temperature float32       `json:"temperature,omitempty"`
	MaxTokens   int           `json:"max_tokens,omitempty"`
	Stream      bool          `json:"stream,omitempty"`
	Tools       []ToolDef     `json:"tools,omitempty"`
}

// InferenceResponse is the standard response from any inference source.
type InferenceResponse struct {
	Version int          `json:"version"`
	Model   ModelID      `json:"model"`
	Message ChatMessage  `json:"message"`
	Usage   TokenUsage   `json:"usage"`
	Done    bool         `json:"done"`
	Latency LatencyStats `json:"latency,omitempty"`
}

// ToolDef defines a tool that the model can call.
type ToolDef struct {
	Version  int            `json:"version"`
	Type     string         `json:"type"` // "function"
	Function ToolDefDetails `json:"function"`
}

// ToolDefDetails contains the tool name, description, and parameter schema.
type ToolDefDetails struct {
	Version     int         `json:"version"`
	Name        string      `json:"name"`
	Description string      `json:"description"`
	Parameters  interface{} `json:"parameters"` // JSON Schema object
}

// LatencyStats captures timing information for observability.
type LatencyStats struct {
	Version      int     `json:"version"`
	PromptEvalMs float64 `json:"prompt_eval_ms,omitempty"`
	GenerationMs float64 `json:"generation_ms,omitempty"`
	TotalMs      float64 `json:"total_ms"`
	TokensPerSec float64 `json:"tokens_per_sec,omitempty"`
}
